use std::{fs,path::Path};
fn main(){let p=Path::new("/tmp/zopro-prefix-stages/measure-repaired.rs");let mut s=fs::read_to_string(p).unwrap();s=s.replace("fn inspect(v:&Value,pool:bool)->Value", "fn inspect(v:&Value,pool:bool,primary:bool)->Value");let start=s.find(" for required in [").unwrap();let end=s[start..].find("\n json!({\"records\"").unwrap()+start;
 s.replace_range(start..end,r#" for required in ["sdk.witness","sdk.serialization","prover.encode","prover.solve_rerandomized","prover.verify","core.external_entry","core.assemble_randomized"]{event(es,required);}
 if primary {for required in ["core.solve_wires","core.public_correction","core.canonical_wires","core.gather_queries","core.product_fft","core.query_join","core.encode_parts","core.A_query","core.KH_query","core.B2_query"]{event(es,required);}}
 let handoffs=if !primary{assert!(!stages.contains_key("core.prefix_worker"));assert!(!stages.contains_key("core.worker_entry"));json!({})}else if pool{assert!(!stages.contains_key("core.worker_entry"));json!({"prefix":handoff(es,"core.prefix_install","core.prefix_worker"),"math":handoff(es,"core.math_join","core.math_worker")})}else{assert!(!stages.contains_key("core.prefix_worker"));let c=event(es,"core.external_entry");let w=event(es,"core.worker_entry");json!({"ordinary":json!({"dispatch_ms":gap(start(c),start(w)),"return_ms":gap(end(w),end(c)),"worker_ms":gap(start(w),end(w)),"caller_ms":gap(start(c),end(c))})})};"#);
 s=s.replace("let o=inspect(c,mode==\"pool\"&&job[\"case\"][\"name\"]==\"1x2-w32\");", "let o=inspect(c,mode==\"pool\"&&job[\"case\"][\"name\"]==\"1x2-w32\",job[\"case\"][\"name\"]==\"1x2-w32\");");s=s.replace("for rel in [\"measure\",\"closeout\",", "for rel in [\"measure\",\"measure-repaired.rs\",\"measure-repaired\",\"analyzer-repair.md\",\"repair-analyzer.rs\",\"measure-repaired-tests.log\",\"closeout\",");fs::write(p,s).unwrap();}
